qualified_questions.sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?type
WHERE {
    :isNeighbourhoodOf rdf:type ?type
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?range
WHERE {
    :readWrite rdfs:range ?range .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?property
WHERE {
    ?property rdf:type owl:FunctionalProperty .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?property
WHERE {
    ?property rdfs:subPropertyOf owl:topDataProperty .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?property
WHERE {
    ?property rdf:type owl:TransitiveProperty .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?property
WHERE {
    ?property rdf:type owl:InverseFunctionalProperty .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
    ?property rdf:type owl:DatatypeProperty .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
    ?property rdf:type owl:ObjectProperty .
}

PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>
PREFIX prov: <http://www.w3.org/ns/prov#>

SELECT ?primarySource
WHERE {
    s4bldg:Building prov:hadPrimarySource ?primarySource.
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://www.w3.org/ns/ssn/system#>

SELECT ?property
WHERE {
    ?property rdfs:subPropertyOf ssn:hasProperty .
}

PREFIX ssn-system: <http://www.w3.org/ns/ssn/system#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>

SELECT ?property
WHERE {
    ?property rdfs:subPropertyOf ssn:hasProperty .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?feature
WHERE {
    ?feature rdfs:subClassOf geo:Feature .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?x
WHERE {
    ?x rdfs:subClassOf foaf:Person
}

PREFIX saref: <https://w3id.org/saref#>

SELECT ?purpose
WHERE {
    saref:Service rdfs:isDefinedBy ?purpose
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX ssn: <http://www.w3.org/ns/ssn/>

SELECT ?role
WHERE {
    sosa:ActuatableProperty rdfs:subClassOf ?role .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?meaning
WHERE {
    ?meaning rdfs:subClassOf geo:Feature .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?concept
WHERE {
    ?concept rdfs:subClassOf foaf:Person .
}

# Write your query here.
SELECT ?idea
WHERE {
    ssn-system:Condition rdfs:subClassOf ?idea .
}

# Write your query here.
SELECT ?meaning
WHERE {
    ssn-system:BatteryLifetime rdfs:subClassOf ?meaning .
}

# Write your query here.
SELECT ?concept
WHERE {
    :Ecosystem rdf:type owl:Class .
    BIND(:Ecosystem AS ?concept)
}

