PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT ?creator
WHERE {
    <http://iot.linkeddata.es/def/core#> dcterms:creator ?creator .
}

# Write your query here.
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?importedOntology
WHERE {
    <http://iot.linkeddata.es/def/core#> owl:imports ?importedOntology.
}

# Write your query here.
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT ?creator ?contributor
WHERE {
    <http://iot.linkeddata.es/def/core#> dcterms:creator ?creator .
    OPTIONAL { <http://iot.linkeddata.es/def/core#> dcterms:contributor ?contributor . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT (COUNT(?contributor) AS ?numContributors)
WHERE {
    ?project dcterms:contributor ?contributor.
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT (COUNT(?annotation) AS ?annotationCount)
WHERE {
    ?annotation rdf:type owl:AnnotationProperty .
}
